137	    /** A rate figure with its late charge (taken as open or not) on top, then at least the sheet's
138	     *  floor in force on the claim's date (a correction has no floor); null when the figure is. */
139	    private BigDecimal floored(Basis basis, Person person, Claim claim, BigDecimal figure, boolean open) {
140	        if (figure == null) {
141	            return null;
