197	    /** The late charge on a claim taken as open (or pending) or not, overdue on the sheet's today (its {@link #lateFrom}
198	     *  before today; a correction has none): for each full 30 days it is overdue, the late percent in force on
199	     *  that boundary (its late-from plus 30, 60, 90 ... days) of its figure plus the charges of the boundaries
200	     *  before it (the charge compounds), rounded to two decimals by the claim's
201	     *  {@link #rounding}, the charges added up (a boundary whose percent is 0.00 adds nothing); 0.00 when it is not overdue. */
202	    private BigDecimal lateCharge(Basis basis, Person person, Claim claim, BigDecimal figure, boolean open) {
203	        BigDecimal none = BigDecimal.ZERO.setScale(2);
204	        LocalDate today = basis.today();
205	        if (!open || claim.isCorrection() || claim.isDeferredOn(today)) {
206	            return none;
207	        }
208	        LocalDate lateFrom = lateFrom(basis, person, claim);
209	        long periods = ChronoUnit.DAYS.between(lateFrom, today) / 30;
210	        if (periods <= 0) {
211	            return none;
212	        }
213	        RoundingMode rounding = rounding(basis, claim);
214	        BigDecimal charge = none;
215	        for (long n = 1; n <= periods; n++) {
216	            BigDecimal pct = basis.latePct(lateFrom.plusDays(30 * n));
217	            if (pct.signum() != 0) {
218	                charge = charge.add(figure.add(charge).multiply(pct).movePointLeft(2).setScale(2, rounding));
219	            }
220	        }
