237	        ClaimStatus then = claim.statusOn(end);
238	        return then != null && then.counts() && !claim.isDeferredOn(today) && !leftOut(person, claim, today);
239	    }
240	
241	    /** Whether the live rules leave a claim of the person out: it is open (or pending) now, unbound
242	     *  by a statement, and dated within one of the person's holds or the person is retired on the
243	     *  sheet's today. */
244	    private static boolean leftOut(Person person, Claim claim, LocalDate today) {
245	        return claim.getStatus().isOpen() && !claim.isStated()
246	                && (person.isHeldOn(claim.getDate()) || person.isRetiredOn(today));
247	    }
248	
249	    /** The claims of a person that count in the live totals on the sheet's today. */
250	    public static List<Claim> live(Person person, List<Claim> theirs, LocalDate today) {
251	        return theirs.stream().filter(c -> countsLive(person, c, today)).toList();
252	    }
253	
254	    /** A person's due-total: the sum of the figures of their claims that count, at most the sheet's
255	     *  cap in force on its today; null (n/a) when their grade on the sheet's today has no rate on it and no counting claim
256	     *  has a figure (one fixed, or a live due at the grade in force on its date). */
257	    public BigDecimal dueTotal(String sheetId, Person person, List<Claim> theirs) {
258	        return dueTotal(now(sheetId), person, theirs);
259	    }
260	
261	    /** A person's due-total on a basis (see {@link #dueTotal(String, Person, List)}). */
262	    public BigDecimal dueTotal(Basis basis, Person person, List<Claim> theirs) {
263	        List<BigDecimal> figures = theirs.stream().filter(c -> c.getStatus().counts())
264	                .map(c -> figure(basis, person, c)).filter(d -> d != null).toList();
265	        LocalDate today = basis.today();
266	        boolean rated = basis.rateInForce(person.gradeOn(today), today).isPresent();
267	        if (!rated && figures.isEmpty()) {
268	            return null;
269	        }
270	        BigDecimal sum = figures.stream().reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
271	        BigDecimal cap = basis.cap();
272	        return cap == null ? sum : sum.min(cap);
273	    }
274	
275	    /** A claim's live due at the rate, in force on the claim's date, for the person's grade in force
276	     *  on that date (taken from the sheet's ancestors when it has none
277	     *  of its own in force then): amount times pct divided by 100, rounded to two decimals by the claim's {@link #rounding} (the floor is
278	     *  applied later, see {@link #floored}); null when no rate applies on that date. */
279	    private BigDecimal due(Basis basis, Person person, Claim claim) {
280	        RoundingMode rounding = rounding(basis, claim);
281	        return basis.rateInForce(person.gradeOn(claim.getDate()), claim.getDate())
282	                .map(Rate::getPct)
283	                .map(pct -> claim.getAmount().multiply(pct).movePointLeft(2).setScale(2, rounding))
284	                .orElse(null);
285	    }
286	
287	    /** How a claim's live figures round: half up when the date it rounds by (a correction's is that of
288	     *  the claim it corrects) is before the sheet's policy date, else half to even. */
289	    private RoundingMode rounding(Basis basis, Claim claim) {
290	        return claim.roundsBy().isBefore(basis.policyDateInForce()) ? RoundingMode.HALF_UP
291	                : RoundingMode.HALF_EVEN;
292	    }
293	}
