1	package net.officefloor.hq.app.claim;
2	
3	import java.math.BigDecimal;
4	import java.time.LocalDate;
5	import java.util.List;
6	import java.util.Optional;
7	import net.officefloor.hq.app.Audit;
8	import net.officefloor.hq.app.holiday.HolidayService;
9	import net.officefloor.hq.app.period.PeriodRepository;
10	import net.officefloor.hq.app.person.Person;
11	import net.officefloor.hq.app.person.PersonRepository;
12	import net.officefloor.hq.app.role.RoleService;
13	import net.officefloor.hq.app.role.SheetRole;
14	import net.officefloor.hq.app.rollup.Rollup;
15	import net.officefloor.hq.app.sheet.SheetService;
16	import net.officefloor.hq.app.voidreason.VoidReasonService;
17	import net.officefloor.hq.app.watch.WatchService;
18	import org.springframework.http.HttpStatus;
19	import org.springframework.stereotype.Service;
20	import org.springframework.transaction.annotation.Transactional;
21	import org.springframework.web.server.ResponseStatusException;
22	
23	/** The claims people make on a sheet. */
24	@Service
25	public class ClaimService {
26	
27	    private final ClaimRepository claims;
28	    private final PersonRepository people;
29	    private final Dues dues;
30	    private final SheetService sheets;
31	    private final Rollup rollup;
32	    private final PeriodRepository periods;
33	    private final RoleService roles;
34	    private final WatchService watches;
35	    private final HolidayService holidays;
36	    private final SheetTagRepository sheetTags;
37	    private final VoidReasonService voidReasons;
38	    private final Audit audit;
39	
40	    /** How many days after its settlement a steward may still void a settled claim. */
41	    static final int VOID_SETTLED_DAYS = 7;
42	
43	    public ClaimService(ClaimRepository claims, PersonRepository people, Dues dues, SheetService sheets,
44	            Rollup rollup, PeriodRepository periods, RoleService roles, WatchService watches,
45	            HolidayService holidays, SheetTagRepository sheetTags, VoidReasonService voidReasons, Audit audit) {
46	        this.claims = claims;
47	        this.people = people;
48	        this.dues = dues;
49	        this.sheets = sheets;
50	        this.rollup = rollup;
51	        this.periods = periods;
52	        this.roles = roles;
53	        this.watches = watches;
54	        this.holidays = holidays;
55	        this.sheetTags = sheetTags;
56	        this.voidReasons = voidReasons;
57	        this.audit = audit;
58	    }
59	
60	    /** The claims on the sheet, newest first. */
61	    @Transactional(readOnly = true)
62	    public List<Claim> list(String sheetId) {
63	        return claims.findBySheetIdOrderByListedDesc(sheetId);
64	    }
65	
66	    /** Add a claim for a person; a date left out takes the sheet's entry date, or its today when none
67	     *  is set. Refused when the due-by it
68	     *  would be fixed with falls inside a closed period, or after the person's retirement day, and when a correction (a negative
69	     *  amount) does not name a settled claim of the person. */
70	    @Transactional
71	    public Claim add(String sheetId, String user, long personId, BigDecimal amount, LocalDate date, String note) {
72	        return add(sheetId, user, personId, amount, date, note, null);
73	    }
74	
75	    /** Add a claim for a person, naming the number of the claim it corrects (only a correction keeps it). */
76	    @Transactional
77	    public Claim add(String sheetId, String user, long personId, BigDecimal amount, LocalDate date, String note,
78	            String corrects) {
79	        return add(sheetId, user, personId, amount, date, note, corrects, null);
80	    }
81	
82	    /** Add a claim for a person with an external reference (null: none); refused as well when another
83	     *  claim of the sheet has the reference, comparing without regard to case. */
84	    @Transactional
85	    public Claim add(String sheetId, String user, long personId, BigDecimal amount, LocalDate date, String note,
86	            String corrects, String ref) {
87	        return add(sheetId, user, personId, amount, date, note, corrects, ref, null);
88	    }
89	
90	    /** Add a claim for a person with tags (as {@link Tags} stores them; null: none). */
91	    @Transactional
92	    public Claim add(String sheetId, String user, long personId, BigDecimal amount, LocalDate date, String note,
93	            String corrects, String ref, String tags) {
94	        refuseRefUsed(sheetId, ref, null);
95	        LocalDate on = date != null ? date : sheets.entryDay(sheetId);
96	        int terms = terms(sheetId, person(sheetId, personId), on);
97	        LocalDate dueBy = holidays.businessDaysAfter(sheetId, on, terms);
98	        refuseClosed(sheetId, dueBy);
99	        refuseRetired(person(sheetId, personId), on);
100	        Claim corrected = corrected(sheetId, personId, amount, corrects);
101	        return rollup.tracking(sheetId, user, () -> {
102	            Person person = person(sheetId, personId);
103	            Claim draft = new Claim(sheetId, personId, amount, on, note,
104	                    corrected == null ? null : corrected.getNumber(), corrected == null ? null : corrected.getDate(),
105	                    dueBy);
106	            draft.setTerms(terms);
107	            draft.setRef(ref);
108	            draft.setTags(tags);
109	            boolean late = periods.softClosedOn(sheetId, dueBy);
110	            if (late) {
111	                draft.markLateEntry();
112	            }
113	            logStatus(sheetId, user, person, draft);
114	            Claim claim = claims.saveAndFlush(draft);
115	            audit.recordOnCommit(record("CLAIM_ADDED", sheetId, user, person, claim)
116	                    + (ref != null ? " ref=" + ref : "") + (tags != null ? " tags=" + tags : ""));
117	            keepTags(sheetId, tags);
118	            if (late) {
119	                audit.recordOnCommit(record("LATE_ENTRY", sheetId, user, person, claim));
120	            }
121	            return claim;
122	        });
123	    }
124	
125	    /** Change a draft claim's amount, date, note and external reference (null: none); a date left out
126	     *  takes the sheet's today. Refused when another claim of the sheet has the reference, and
127	     *  when the claim is not a draft (an open claim is changed by voiding it and adding a new one), and
128	     *  when the claim's due-by (which the edit leaves) falls inside a closed period, and when the new
129	     *  date is after the person's retirement day, and when the claim has lines and the amount is not
130	     *  their total (400). */
131	    @Transactional
132	    public Claim edit(String sheetId, String user, long claimId, BigDecimal amount, LocalDate date, String note,
133	            String corrects, String ref, String tags) {
134	        Claim claim = lock(sheetId, claimId);
135	        if (claim.getStatus() != ClaimStatus.DRAFT || claim.editLockedFor(user)) {
136	            throw new ResponseStatusException(HttpStatus.CONFLICT,
137	                    "A " + claim.getStatus() + " claim cannot be edited, nor one another user is editing");
138	        }
139	        refuseRefUsed(sheetId, ref, claim.getId());
140	        LocalDate on = date != null ? date : sheets.today(sheetId);
141	        refuseClosed(sheetId, claim.getDueBy());
142	        refuseRetired(person(sheetId, claim.getPersonId()), on);
143	        if (!claim.getLines().isEmpty() && amount.compareTo(claim.getAmount()) != 0) {
144	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
145	                    "A claim with lines has their total as its amount");
146	        }
147	        Claim corrected = corrected(sheetId, claim.getPersonId(), amount, corrects);
148	        return rollup.tracking(sheetId, user, () -> {
149	            claim.setAmount(amount);
150	            claim.setCorrects(corrected == null ? null : corrected.getNumber());
151	            claim.setCorrectedDate(corrected == null ? null : corrected.getDate());
152	            claim.setDate(on);
153	            claim.setNote(note);
154	            claim.setRef(ref);
155	            claim.setTags(tags);
156	            claim.setEditLockedBy(null);
157	            claim.setEditedBy(user);
158	            keepTags(sheetId, tags);
159	            Claim saved = claims.saveAndFlush(claim);
160	            audit.recordOnCommit(record("CLAIM_EDITED", sheetId, user, person(sheetId, saved.getPersonId()), saved));
161	            return saved;
162	        });
163	    }
164	
165	    /** Change only a draft claim's amount (the row's inline entry), keeping its date, note and the
166	     *  number it corrects; refused exactly as {@link #edit} refuses, and recorded as it records. */
167	    @Transactional
168	    public Claim editAmount(String sheetId, String user, long claimId, BigDecimal amount) {
169	        Claim claim = lock(sheetId, claimId);
170	        return edit(sheetId, user, claimId, amount, claim.getDate(), claim.getNote(), claim.getCorrects(),
171	                claim.getRef(), claim.getTags());
172	    }
173	
174	    /** Open a claim's editor for the user, locking the claim for every other user until it is saved
175	     *  or cancelled or the sheet's today changes; an editor the user had open on another claim of the
176	     *  same person is closed. Refused when the claim is not a draft or another user has its editor
177	     *  open (409), and when its due-by falls inside a closed period (423). Records nothing. */
178	    @Transactional
179	    public Claim openEditor(String sheetId, String user, long claimId) {
180	        Claim claim = lock(sheetId, claimId);
181	        if (claim.getStatus() != ClaimStatus.DRAFT || claim.editLockedFor(user)) {
182	            throw new ResponseStatusException(HttpStatus.CONFLICT,
183	                    "A " + claim.getStatus() + " claim cannot be edited, nor one another user is editing");
184	        }
185	        refuseClosed(sheetId, claim.getDueBy());
186	        claims.releaseOtherEditLocks(sheetId, claim.getPersonId(), user, claim.getId());
187	        claim.setEditLockedBy(user);
188	        return claims.saveAndFlush(claim);
189	    }
190	
191	    /** Close the claim's editor the user has open (cancelled), unlocking the claim; a claim whose
192	     *  editor the user does not have open is left as it is. Records nothing. */
193	    @Transactional
194	    public Claim closeEditor(String sheetId, String user, long claimId) {
195	        Claim claim = lock(sheetId, claimId);
196	        if (!user.equals(claim.getEditLockedBy())) {
197	            return claim;
198	        }
199	        claim.setEditLockedBy(null);
200	        return claims.saveAndFlush(claim);
201	    }
202	
203	    /** Move a claim to a new status; a change its current status does not allow is refused, and so
204	     *  is settling a claim by the user who opened or last edited it, and any change to a claim whose due-by falls inside a
205	     *  closed period, and any change the permission matrix does not allow the user's role. A clerk settling a claim whose due is above the sheet's clerk limit leaves it pending
206	     *  a steward's approval instead; but settling a claim that needs a proof and has none is refused
207	     *  before the clerk limit is considered. */
208	    @Transactional
209	    public Claim changeStatus(String sheetId, String user, long claimId, ClaimStatus to) {
210	        return changeStatus(sheetId, user, claimId, to, null);
211	    }
212	
213	    /** Number the claims a bulk settle settled (or left pending) as the sheet's next settle batch;
214	     *  nothing when it settled none (0). Returns the batch's number. */
215	    @Transactional
216	    public int markSettleBatch(String sheetId, List<Long> claimIds) {
217	        if (claimIds.isEmpty()) {
218	            return 0;
219	        }
220	        int batch = sheets.nextSettleBatch(sheetId);
221	        for (Long claimId : claimIds) {
222	            Claim claim = lock(sheetId, claimId);
223	            claim.setSettleBatch(batch);
224	            claims.saveAndFlush(claim);
225	        }
226	        return batch;
227	    }
228	
229	    /** Void a claim as {@link #changeStatus} does; while the sheet has void reasons, the void needs
230	     *  one of them (refused without), kept on the claim and ending its record. */
231	    @Transactional
232	    public Claim voidClaim(String sheetId, String user, long claimId, String reason) {
233	        return changeStatus(sheetId, user, claimId, ClaimStatus.VOID, reason);
234	    }
235	
236	    private Claim changeStatus(String sheetId, String user, long claimId, ClaimStatus to, String reason) {
237	        Claim claim = lock(sheetId, claimId);
238	        refuseClosed(sheetId, claim.getDueBy());
239	        String voidReason = to == ClaimStatus.VOID ? voidReasons.required(sheetId, reason) : null;
240	        if (to == ClaimStatus.VOID && claim.getStatus() == ClaimStatus.SETTLED) {
241	            return voidSettled(sheetId, user, claim, voidReason);
242	        }
243	        if (!claim.getStatus().canBecome(to) || to == ClaimStatus.PENDING) {
244	            throw new ResponseStatusException(HttpStatus.CONFLICT,
245	                    "A " + claim.getStatus() + " claim cannot become " + to);
246	        }
247	        String action = switch (to) {
248	            case OPEN -> "open";
249	            case SETTLED -> "settle";
250	            default -> "void";
251	        };
252	        if (!roles.may(sheetId, user, action)) {
253	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Your role may not " + action + " a claim");
254	        }
255	        if (to == ClaimStatus.OPEN) {
256	            refuseUnnoted(sheetId, claim);
257	            refuseOverCap(sheetId, claim);
258	        }
259	        if (to == ClaimStatus.SETTLED && claim.isDeferredOn(sheets.today(sheetId))) {
260	            throw new ResponseStatusException(HttpStatus.CONFLICT,
261	                    "A claim deferred until " + claim.getDeferredUntil() + " cannot be settled before then");
262	        }
263	        if (to == ClaimStatus.SETTLED && claim.openedOrEditedBy(user)) {
264	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
265	                    "The user who opened or last edited a claim cannot settle it");
266	        }
267	        if (to == ClaimStatus.SETTLED) {
268	            refuseUnproved(sheetId, claim);
269	        }
270	        ClaimStatus becomes = to == ClaimStatus.SETTLED && overClerkLimit(sheetId, user, claim)
271	                ? ClaimStatus.PENDING : to;
272	        return rollup.tracking(sheetId, user, () -> {
273	            Person person = person(sheetId, claim.getPersonId());
274	            if (becomes == ClaimStatus.SETTLED) {
275	                // Settling fixes the due at what it is now, while the claim is still open (the figure a
276	                // statement bound it to, if any, and its late charge); later changes to rates, the
277	                // late percent and the sheet's today do not alter it.
278	                claim.setSettledDue(dues.figure(sheetId, person, claim));
279	            }
280	            // A void claim keeps the number it had (never reused).
281	            claim.setStatus(becomes);
282	            if (becomes == ClaimStatus.VOID) {
283	                claim.setVoidReason(voidReason);
284	            }
285	            if (becomes == ClaimStatus.OPEN) {
286	                claim.setNumber(nextNumber(sheetId, claim.getDueBy()));
287	                claim.setOpenedBy(user);
288	            }
289	            logStatus(sheetId, user, person, claim);
290	            Claim saved = claims.saveAndFlush(claim);
291	            String event = switch (becomes) {
292	                case OPEN -> "CLAIM_OPENED";
293	                case PENDING -> "CLAIM_PENDING";
294	                case SETTLED -> "CLAIM_SETTLED";
295	                case VOID -> "CLAIM_VOIDED";
296	                case DRAFT, DELETED -> throw new IllegalStateException("a claim is deleted or restored apart");
297	            };
298	            String line = record(event, sheetId, user, person, saved);
299	            if (becomes == ClaimStatus.SETTLED) {
300	                line += " due=" + dueText(saved.getSettledDue());
301	            }
302	            line += reasonText(voidReason);
303	            audit.recordOnCommit(line);
304	            if (becomes == ClaimStatus.SETTLED) {
305	                watches.notifyWatchers(sheetId, user, person, saved.getNumber());
306	            }
307	            return saved;
308	        });
309	    }
310	
311	    /** Delete a draft claim: it counts nowhere, and cannot be edited, opened or voided. Refused when
312	     *  the claim is not a draft, or its period is closed. */
313	    @Transactional
314	    public Claim delete(String sheetId, String user, long claimId) {
315	        Claim claim = lock(sheetId, claimId);
316	        refuseClosed(sheetId, claim.getDueBy());
317	        if (!claim.getStatus().canBecome(ClaimStatus.DELETED) || claim.editLockedFor(user)) {
318	            throw new ResponseStatusException(HttpStatus.CONFLICT,
319	                    "A " + claim.getStatus() + " claim cannot be deleted, nor one another user is editing");
320	        }
321	        return rollup.tracking(sheetId, user, () -> {
322	            Person person = person(sheetId, claim.getPersonId());
323	            claim.setStatus(ClaimStatus.DELETED);
324	            claim.setEditLockedBy(null);
325	            logStatus(sheetId, user, person, claim);
326	            Claim saved = claims.saveAndFlush(claim);
327	            audit.recordOnCommit(record("CLAIM_DELETED", sheetId, user, person, saved));
328	            return saved;
329	        });
330	    }
331	
332	    /** Restore a deleted claim to a draft. Refused when the claim is not deleted, it was deleted on
333	     *  another day than the sheet's today, or its period is closed. */
334	    @Transactional
335	    public Claim restore(String sheetId, String user, long claimId) {
336	        Claim claim = lock(sheetId, claimId);
337	        refuseClosed(sheetId, claim.getDueBy());
338	        if (claim.getStatus() != ClaimStatus.DELETED) {
339	            throw new ResponseStatusException(HttpStatus.CONFLICT,
340	                    "A " + claim.getStatus() + " claim cannot be restored");
341	        }
342	        LocalDate deleted = claim.getLog().stream().filter(l -> l.getStatus() == ClaimStatus.DELETED)
343	                .map(ClaimLog::getOn).reduce((first, last) -> last).orElse(null);
344	        if (!sheets.today(sheetId).equals(deleted)) {
345	            throw new ResponseStatusException(HttpStatus.CONFLICT,
346	                    "A deleted claim can only be restored on the day it was deleted");
347	        }
348	        return rollup.tracking(sheetId, user, () -> {
349	            Person person = person(sheetId, claim.getPersonId());
350	            claim.setStatus(ClaimStatus.DRAFT);
351	            logStatus(sheetId, user, person, claim);
352	            Claim saved = claims.saveAndFlush(claim);
353	            audit.recordOnCommit(record("CLAIM_RESTORED", sheetId, user, person, saved));
354	            return saved;
355	        });
356	    }
357	
358	    /** Void a settled claim: only a steward may, within {@value #VOID_SETTLED_DAYS} days of its
359	     *  settlement (the first SETTLED line of its status log) by the sheet's today. It keeps its
360	     *  number and settled due, which leaves every total; the record ends with the figure reversed. */
361	    private Claim voidSettled(String sheetId, String user, Claim claim, String voidReason) {
362	        if (!SheetRole.STEWARD.equals(roles.roleOf(sheetId, user))) {
363	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward can void a settled claim");
364	        }
365	        LocalDate today = sheets.today(sheetId);
366	        LocalDate settled = claim.getLog().stream().filter(l -> l.getStatus() == ClaimStatus.SETTLED)
367	                .map(ClaimLog::getOn).findFirst().orElse(null);
368	        if (settled == null || today.isBefore(settled) || today.isAfter(settled.plusDays(VOID_SETTLED_DAYS))) {
369	            throw new ResponseStatusException(HttpStatus.CONFLICT,
370	                    "A settled claim can only be voided within " + VOID_SETTLED_DAYS + " days of its settlement");
371	        }
372	        return rollup.tracking(sheetId, user, () -> {
373	            Person person = person(sheetId, claim.getPersonId());
374	            BigDecimal reversed = dues.figure(sheetId, person, claim);
375	            claim.setStatus(ClaimStatus.VOID);
376	            claim.setVoidReason(voidReason);
377	            logStatus(sheetId, user, person, claim);
378	            Claim saved = claims.saveAndFlush(claim);
379	            audit.recordOnCommit(record("CLAIM_VOIDED", sheetId, user, person, saved) + " reversed=" + dueText(reversed)
380	                    + reasonText(voidReason));
381	            return saved;
382	        });
383	    }
384	
385	    /** Defer an open claim until a day after the sheet's today: until the sheet's today reaches it,
386	     *  the claim counts in no total, is not overdue, cannot be settled and a statement leaves it
387	     *  unbound. Refused when the claim's period is closed, the claim is not open, or the day is not
388	     *  after the sheet's today. */
389	    @Transactional
390	    public Claim defer(String sheetId, String user, long claimId, LocalDate until) {
391	        Claim claim = lock(sheetId, claimId);
392	        refuseClosed(sheetId, claim.getDueBy());
393	        if (claim.getStatus() != ClaimStatus.OPEN) {
394	            throw new ResponseStatusException(HttpStatus.CONFLICT,
395	                    "A " + claim.getStatus() + " claim cannot be deferred");
396	        }
397	        if (!until.isAfter(sheets.today(sheetId))) {
398	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
399	                    "A claim can only be deferred to a date after the sheet's today");
400	        }
401	        return rollup.tracking(sheetId, user, () -> {
402	            Person person = person(sheetId, claim.getPersonId());
403	            claim.deferUntil(until);
404	            Claim saved = claims.saveAndFlush(claim);
405	            audit.recordOnCommit(record("CLAIM_DEFERRED", sheetId, user, person, saved) + " until=" + until);
406	            return saved;
407	        });
408	    }
409	
410	    /** Raise a claim's proofs count by one. Refused when the claim is settled or void, or its period
411	     *  is closed. It changes no figure. */
412	    @Transactional
413	    public Claim addProof(String sheetId, String user, long claimId) {
414	        Claim claim = lock(sheetId, claimId);
415	        refuseClosed(sheetId, claim.getDueBy());
416	        if (claim.getStatus() == ClaimStatus.SETTLED || claim.getStatus() == ClaimStatus.VOID
417	                || claim.getStatus() == ClaimStatus.DELETED) {
418	            throw new ResponseStatusException(HttpStatus.CONFLICT,
419	                    "A " + claim.getStatus() + " claim cannot be given a proof");
420	        }
421	        Person person = person(sheetId, claim.getPersonId());
422	        claim.addProof(sheets.today(sheetId));
423	        Claim saved = claims.saveAndFlush(claim);
424	        audit.recordOnCommit(record("CLAIM_PROOF_ADDED", sheetId, user, person, saved) + " proofs=" + saved.getProofs());
425	        return saved;
426	    }
427	
428	    /** Remind an open or pending claim: it is reminded on the sheet's today. Refused when the claim
429	     *  is in any other status, and when it was already reminded on the sheet's today. It changes no
430	     *  figure. */
431	    @Transactional
432	    public Claim remind(String sheetId, String user, long claimId) {
433	        Claim claim = lock(sheetId, claimId);
434	        if (claim.getStatus() != ClaimStatus.OPEN && claim.getStatus() != ClaimStatus.PENDING) {
435	            throw new ResponseStatusException(HttpStatus.CONFLICT,
436	                    "A " + claim.getStatus() + " claim cannot be reminded");
437	        }
438	        LocalDate today = sheets.today(sheetId);
439	        if (today.equals(claim.getRemindedOn())) {
440	            throw new ResponseStatusException(HttpStatus.TOO_MANY_REQUESTS,
441	                    "The claim was already reminded today");
442	        }
443	        Person person = person(sheetId, claim.getPersonId());
444	        claim.remindOn(today);
445	        Claim saved = claims.saveAndFlush(claim);
446	        audit.recordOnCommit(record("REMIND", sheetId, user, person, saved));
447	        return saved;
448	    }
449	
450	    /** Comment a claim, in any status: the comment is kept with the user and the sheet's today. Refused
451	     *  when the text is empty. It changes no figure. */
452	    @Transactional
453	    public Claim comment(String sheetId, String user, long claimId, String text) {
454	        String trimmed = text == null ? "" : text.trim();
455	        if (trimmed.isEmpty()) {
456	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A comment cannot be empty");
457	        }
458	        Claim claim = lock(sheetId, claimId);
459	        Person person = person(sheetId, claim.getPersonId());
460	        claim.comment(user, sheets.today(sheetId), trimmed);
461	        Claim saved = claims.saveAndFlush(claim);
462	        audit.recordOnCommit(record("COMMENT_ADDED", sheetId, user, person, saved) + " text=" + trimmed);
463	        return saved;
464	    }
465	
466	    /** Add a line to a draft claim: its amount becomes the lines' quantities times unit amounts added
467	     *  up. Refused when the label is empty, the quantity is below 1 or the unit amount below 0.01
468	     *  (400), when the claim is not a draft or another user has its editor open (409), and when its
469	     *  due-by falls inside a closed period. Counts as editing the claim. */
470	    @Transactional
471	    public Claim addLine(String sheetId, String user, long claimId, String label, int qty, BigDecimal unit) {
472	        String trimmed = label == null ? "" : label.trim();
473	        if (trimmed.isEmpty() || qty < 1 || unit.signum() <= 0) {
474	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
475	                    "A line needs a label, a quantity of at least 1 and a unit amount above 0.00");
476	        }
477	        Claim claim = lock(sheetId, claimId);
478	        if (claim.getStatus() != ClaimStatus.DRAFT || claim.editLockedFor(user)) {
479	            throw new ResponseStatusException(HttpStatus.CONFLICT,
480	                    "A " + claim.getStatus() + " claim cannot be given a line, nor one another user is editing");
481	        }
482	        refuseClosed(sheetId, claim.getDueBy());
483	        return rollup.tracking(sheetId, user, () -> {
484	            Person person = person(sheetId, claim.getPersonId());
485	            claim.addLine(trimmed, qty, unit);
486	            claim.setEditedBy(user);
487	            Claim saved = claims.saveAndFlush(claim);
488	            audit.recordOnCommit(record("CLAIM_LINE_ADDED", sheetId, user, person, saved)
489	                    + " label=" + trimmed + " qty=" + qty + " unit=" + unit.setScale(2).toPlainString());
490	            return saved;
491	        });
492	    }
493	
494	    /** Approve a pending claim: it becomes settled, its due fixed at the figure it has now (its live
495	     *  figure and late charge). Refused unless the claim is pending, the user is a steward and is not
496	     *  the one who opened or last edited it, the claim's period is open, and it has a proof if it needs one. */
497	    @Transactional
498	    public Claim approve(String sheetId, String user, long claimId) {
499	        Claim claim = lockPending(sheetId, user, claimId);
500	        if (claim.openedOrEditedBy(user)) {
501	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
502	                    "The user who opened or last edited a claim cannot approve it");
503	        }
504	        refuseUnproved(sheetId, claim);
505	        return rollup.tracking(sheetId, user, () -> {
506	            Person person = person(sheetId, claim.getPersonId());
507	            claim.setSettledDue(dues.figure(sheetId, person, claim));
508	            claim.setStatus(ClaimStatus.SETTLED);
509	            logStatus(sheetId, user, person, claim);
510	            Claim saved = claims.saveAndFlush(claim);
511	            audit.recordOnCommit(record("CLAIM_APPROVED", sheetId, user, person, saved)
512	                    + " due=" + dueText(saved.getSettledDue()));
513	            watches.notifyWatchers(sheetId, user, person, saved.getNumber());
514	            return saved;
515	        });
516	    }
517	
518	    /** Re-settle a settled claim: its due is fixed again at the figure it would have today as an open
519	     *  claim bound by no statement (today's rates, grades, floor and late charge). Refused unless the
520	     *  claim is settled, the user is a steward, and the claim's period is open. */
521	    @Transactional
522	    public Claim resettle(String sheetId, String user, long claimId) {
523	        Claim claim = lock(sheetId, claimId);
524	        refuseClosed(sheetId, claim.getDueBy());
525	        if (claim.getStatus() != ClaimStatus.SETTLED) {
526	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Only a SETTLED claim can be re-settled");
527	        }
528	        if (!SheetRole.STEWARD.equals(roles.roleOf(sheetId, user))) {
529	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward can re-settle a claim");
530	        }
531	        return rollup.tracking(sheetId, user, () -> {
532	            Person person = person(sheetId, claim.getPersonId());
533	            BigDecimal old = dues.figure(sheetId, person, claim);
534	            BigDecimal now = dues.openFigure(sheetId, person, claim);
535	            claim.setSettledDue(now);
536	            claim.logStatus(user, sheets.today(sheetId), now);
537	            Claim saved = claims.saveAndFlush(claim);
538	            audit.recordOnCommit(record("CLAIM_RESETTLED", sheetId, user, person, saved)
539	                    + " old=" + dueText(old) + " new=" + dueText(now));
540	            watches.notifyWatchers(sheetId, user, person, saved.getNumber());
541	            return saved;
542	        });
543	    }
544	
545	    /** Reject a pending claim for a reason: it is open again, bound again by its person's last
546	     *  statement if that statement included it. Refused unless the claim is pending, the user is a
547	     *  steward, and the claim's period is open. */
548	    @Transactional
549	    public Claim reject(String sheetId, String user, long claimId, String reason) {
550	        Claim claim = lockPending(sheetId, user, claimId);
551	        return rollup.tracking(sheetId, user, () -> {
552	            Person person = person(sheetId, claim.getPersonId());
553	            claim.setStatus(ClaimStatus.OPEN);
554	            // back to open, it is no longer settled by the batch that left it pending
555	            claim.setSettleBatch(null);
556	            logStatus(sheetId, user, person, claim);
557	            Claim saved = claims.saveAndFlush(claim);
558	            audit.recordOnCommit(record("CLAIM_REJECTED", sheetId, user, person, saved) + " reason=" + reason);
559	            return saved;
560	        });
561	    }
562	
563	    /** Move a draft, open or pending claim to another person on the sheet. It keeps its date and
564	     *  status, takes the next number (a draft, having none, gets none), loses any figure a statement bound it to, and is listed as its new person's newest
565	     *  claim. Refused unless the permission matrix allows the user's role to reassign, and when the claim is settled or void, the person
566	     *  is the one it is already for, the claim's period is closed, or the claim is dated after the
567	     *  new person's retirement day. */
568	    @Transactional
569	    public Claim reassign(String sheetId, String user, long claimId, long toPersonId) {
570	        return reassign(sheetId, user, claimId, toPersonId, false);
571	    }
572	
573	    /** Move a claim as {@link #reassign(String, String, long, long)} does; a bulk move ({@code
574	     *  inBulk}) also takes a claim that is already the person's, listing it as their newest. */
575	    @Transactional
576	    public Claim reassign(String sheetId, String user, long claimId, long toPersonId, boolean inBulk) {
577	        Claim claim = lock(sheetId, claimId);
578	        if (!roles.may(sheetId, user, "reassign")) {
579	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Your role may not reassign a claim");
580	        }
581	        if (claim.getStatus() == ClaimStatus.SETTLED || claim.getStatus() == ClaimStatus.VOID
582	                || claim.getStatus() == ClaimStatus.DELETED) {
583	            throw new ResponseStatusException(HttpStatus.CONFLICT,
584	                    "A " + claim.getStatus() + " claim cannot be reassigned");
585	        }
586	        if (!inBulk && claim.getPersonId() == toPersonId) {
587	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "The claim is already that person's");
588	        }
589	        refuseClosed(sheetId, claim.getDueBy());
590	        Person from = person(sheetId, claim.getPersonId());
591	        Person to = person(sheetId, toPersonId);
592	        refuseRetired(to, claim.getDate());
593	        return rollup.tracking(sheetId, user, () -> {
594	            claim.moveTo(to.getId(), claims.nextListed());
595	            if (claim.getNumber() != null) {
596	                // a moved claim takes the next number; its old one is never used again
597	                claim.setNumber(nextNumber(sheetId, claim.getDueBy()));
598	            }
599	            Claim saved = claims.saveAndFlush(claim);
600	            audit.recordOnCommit(record("CLAIM_REASSIGNED", sheetId, user, to, saved)
601	                    + " from=" + from.getName() + " to=" + to.getName());
602	            return saved;
603	        });
604	    }
605	
606	    /** Re-date an open or pending claim: it keeps the due-by it was fixed with, and so its period and
607	     *  number, and any figure a statement bound it to. Refused unless the user is a steward, and when
608	     *  the claim is not open or pending, its period is closed, or the new date is after the person's
609	     *  retirement day. */
610	    @Transactional
611	    public Claim redate(String sheetId, String user, long claimId, LocalDate date) {
612	        Claim claim = lock(sheetId, claimId);
613	        if (!SheetRole.STEWARD.equals(roles.roleOf(sheetId, user))) {
614	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward can re-date a claim");
615	        }
616	        if (claim.getStatus() != ClaimStatus.OPEN && claim.getStatus() != ClaimStatus.PENDING) {
617	            throw new ResponseStatusException(HttpStatus.CONFLICT,
618	                    "A " + claim.getStatus() + " claim cannot be re-dated");
619	        }
620	        refuseClosed(sheetId, claim.getDueBy());
621	        refuseRetired(person(sheetId, claim.getPersonId()), date);
622	        LocalDate old = claim.getDate();
623	        return rollup.tracking(sheetId, user, () -> {
624	            Person person = person(sheetId, claim.getPersonId());
625	            claim.setDate(date);
626	            Claim saved = claims.saveAndFlush(claim);
627	            audit.recordOnCommit(record("CLAIM_REDATED", sheetId, user, person, saved)
628	                    + " old=" + old + " new=" + date);
629	            return saved;
630	        });
631	    }
632	
633	    /** What a split leaves:the original claim, with the rest of its amount, and the new open claim
634	     *  split off it. */
635	    public record Split(Claim original, Claim split) {
636	    }
637	
638	    /** Split an amount (above 0.00 and below the claim's amount) off an open claim: it keeps the rest
639	     *  of its amount and loses any figure a statement bound it to, and a new open claim of the amount,
640	     *  the same date and note, the next number, opened by the user and due by the terms in force on
641	     *  the date, is listed as its person's newest claim. Refused when the claim is not open (or is
642	     *  deferred), its period is closed, the amount is out of range, or the permission matrix does not
643	     *  allow the user's role to open a claim. */
644	    @Transactional
645	    public Split split(String sheetId, String user, long claimId, BigDecimal part) {
646	        Claim claim = lock(sheetId, claimId);
647	        refuseClosed(sheetId, claim.getDueBy());
648	        if (claim.getStatus() != ClaimStatus.OPEN || claim.isDeferredOn(sheets.today(sheetId))) {
649	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Only an open claim that is not deferred can be split");
650	        }
651	        if (!roles.may(sheetId, user, "open")) {
652	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Your role may not open a claim");
653	        }
654	        if (part.signum() <= 0 || part.compareTo(claim.getAmount()) >= 0) {
655	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
656	                    "The amount split off must be above 0.00 and below the claim's amount");
657	        }
658	        return rollup.tracking(sheetId, user, () -> {
659	            Person person = person(sheetId, claim.getPersonId());
660	            int terms = terms(sheetId, person, claim.getDate());
661	            LocalDate dueBy = holidays.businessDaysAfter(sheetId, claim.getDate(), terms);
662	            Claim draft = claim.splitOff(part, nextNumber(sheetId, dueBy), user, dueBy, terms);
663	            logStatus(sheetId, user, person, draft);
664	            Claim original = claims.saveAndFlush(claim);
665	            Claim split = claims.saveAndFlush(draft);
666	            audit.recordOnCommit(record("CLAIM_SPLIT", sheetId, user, person, original) + " into=" + split.getNumber());
667	            audit.recordOnCommit(record("CLAIM_OPENED", sheetId, user, person, split));
668	            return new Split(original, split);
669	        });
670	    }
671	
672	    /** The pending claim a steward approves or rejects, locked; refused when it is not pending, the
673	     *  user is not a steward, or its period is closed. */
674	    private Claim lockPending(String sheetId, String user, long claimId) {
675	        Claim claim = lock(sheetId, claimId);
676	        refuseClosed(sheetId, claim.getDueBy());
677	        if (claim.getStatus() != ClaimStatus.PENDING) {
678	            throw new ResponseStatusException(HttpStatus.CONFLICT,
679	                    "Only a PENDING claim can be approved or rejected");
680	        }
681	        if (!SheetRole.STEWARD.equals(roles.roleOf(sheetId, user))) {
682	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
683	                    "Only a steward can approve or reject a claim");
684	        }
685	        return claim;
686	    }
687	
688	    /** Log the status the claim has now, changed by the user on the sheet's today, with its due as
689	     *  computed at this moment. */
690	    private void logStatus(String sheetId, String user, Person person, Claim claim) {
691	        claim.logStatus(user, sheets.today(sheetId), dues.figure(sheetId, person, claim));
692	    }
693	
694	    private Claim lock(String sheetId, long claimId) {
695	        return claims.lockByIdAndSheetId(claimId, sheetId)
696	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet"));
697	    }
698	
699	    private static String dueText(BigDecimal due) {
700	        return due == null ? "n/a" : due.setScale(2).toPlainString();
701	    }
702	
703	    /** The number for a claim due by the day opened now: under period numbering, the next in its period
704	     *  (<period name>-<n>), or for one in no period the next X-<n>; otherwise the next on the sheet
705	     *  within the fiscal year of its due-by day (<FY>-<n>). */
706	    public String nextNumber(String sheetId, LocalDate dueBy) {
707	        if (!sheets.periodNumbering(sheetId)) {
708	            return sheets.nextClaimNumber(sheetId, dueBy);
709	        }
710	        return periods.findOn(sheetId, dueBy)
711	                .map(p -> {
712	                    periods.advanceClaimNumber(p.getId());
713	                    return p.getName() + "-" + periods.lastClaimNumber(p.getId());
714	                })
715	                .orElseGet(() -> "X-" + sheets.nextUnperiodNumber(sheetId));
716	    }
717	
718	    /** The claim a claim of the amount corrects: none for an amount of 0.00 or more; for a correction
719	     *  (a negative amount), the one of the number given, which must be a settled claim of the person,
720	     *  or else it is refused. */
721	    private Claim corrected(String sheetId, long personId, BigDecimal amount, String corrects) {
722	        if (amount.signum() >= 0) {
723	            return null;
724	        }
725	        return (corrects == null ? Optional.<Claim>empty()
726	                : claims.findBySheetIdAndPersonIdAndNumberAndStatus(sheetId, personId, corrects, ClaimStatus.SETTLED))
727	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.BAD_REQUEST,
728	                        "A negative amount must correct a settled claim of the same person"));
729	    }
730	
731	    /** Refuse a change to a claim due by the day when the day falls inside a closed period. */
732	    private void refuseClosed(String sheetId, LocalDate day) {
733	        if (periods.closedOn(sheetId, day)) {
734	            throw new ResponseStatusException(HttpStatus.LOCKED, "That claim's period is closed");
735	        }
736	    }
737	
738	    /** Whether a clerk is settling a claim whose due is above the sheet's clerk limit in force on its today; a claim with
739	     *  no due (n/a) is within any limit, and a steward settles anything. */
740	    private boolean overClerkLimit(String sheetId, String user, Claim claim) {
741	        BigDecimal limit = sheets.clerkLimit(sheetId);
742	        if (limit == null || SheetRole.STEWARD.equals(roles.roleOf(sheetId, user))) {
743	            return false;
744	        }
745	        BigDecimal due = dues.figure(sheetId, person(sheetId, claim.getPersonId()), claim);
746	        return due != null && due.compareTo(limit) > 0;
747	    }
748	
749	    /** Refuse settling or approving a claim with no proofs whose due is above the proof threshold in
750	     *  force on the claim's date: its person's grade's (on that date) when one is set, or else the
751	     *  sheet's; a claim with no due (n/a) and a claim with no threshold need none. */
752	    private void refuseUnproved(String sheetId, Claim claim) {
753	        if (claim.getProofs() > 0) {
754	            return;
755	        }
756	        Person person = person(sheetId, claim.getPersonId());
757	        BigDecimal threshold = sheets.proofThresholdFor(sheetId, person.gradeOn(claim.getDate()), claim.getDate());
758	        if (threshold == null) {
759	            return;
760	        }
761	        BigDecimal due = dues.figure(sheetId, person, claim);
762	        if (due != null && due.compareTo(threshold) > 0) {
763	            throw new ResponseStatusException(HttpStatus.PRECONDITION_REQUIRED,
764	                    "A claim whose due is above the proof threshold needs a proof first");
765	        }
766	    }
767	
768	    /** Refuse opening a claim whose period caps its person's claims when the person already has
769	     *  that many open or pending claims due inside it; the period stays locked until the transaction
770	     *  ends, so two claims opened in it at once are counted one after the other. */
771	    private void refuseOverCap(String sheetId, Claim claim) {
772	        periods.findOn(sheetId, claim.getDueBy())
773	                .filter(p -> p.getClaimCap() != null)
774	                .flatMap(p -> periods.lockByIdAndSheetId(p.getId(), sheetId))
775	                .ifPresent(p -> {
776	                    if (claims.countOpenDueBetween(sheetId, claim.getPersonId(), p.getFromDate(), p.getToDate())
777	                            >= p.getClaimCap()) {
778	                        throw new ResponseStatusException(HttpStatus.CONFLICT,
779	                                "The person already has " + p.getClaimCap() + " open claims in period " + p.getName());
780	                    }
781	                });
782	    }
783	
784	    /** Refuse opening a claim with an empty note whose due is above the sheet's note threshold in
785	     *  force on the claim's date; a claim with no due (n/a) and a sheet with no threshold need none. */
786	    private void refuseUnnoted(String sheetId, Claim claim) {
787	        BigDecimal threshold = sheets.noteThreshold(sheetId, claim.getDate());
788	        if (threshold == null || (claim.getNote() != null && !claim.getNote().isBlank())) {
789	            return;
790	        }
791	        BigDecimal due = dues.figure(sheetId, person(sheetId, claim.getPersonId()), claim);
792	        if (due != null && due.compareTo(threshold) > 0) {
793	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
794	                    "A claim whose due is above the note threshold needs a note before it is opened");
795	        }
796	    }
797	
798	    /** Refuse a claim of the person dated after the day they are retired from, or after the from-date
799	     *  and before the to-date of one of their past retirements. */
800	    private static void refuseRetired(Person person, LocalDate day) {
801	        if ((person.getRetiredFrom() != null && day.isAfter(person.getRetiredFrom()))
802	                || person.isWithinPastRetirement(day)) {
803	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
804	                    "A claim cannot be dated after the person's retirement");
805	        }
806	    }
807	
808	    /** The terms a claim of the person dated on the day has its due-by fixed with (the terms-th
809	     *  business day after its date, skipping every Saturday, Sunday and holiday of the sheet): the
810	     *  first of the person's own terms, their grade's and the sheet's, each as in force on the day. */
811	    private int terms(String sheetId, Person person, LocalDate on) {
812	        Integer own = person.getTerms();
813	        return own != null ? own : sheets.termsFor(sheetId, person.gradeOn(on), on);
814	    }
815	
816	    /** Refuse a reference (null: none) another claim of the sheet than the one given (null: any) has,
817	     *  comparing without regard to case. */
818	    /** The tags ever used on the sheet, in order. */
819	    @Transactional(readOnly = true)
820	    public List<String> tags(String sheetId) {
821	        return sheetTags.findBySheetIdOrderByTagAsc(sheetId).stream().map(SheetTag::getTag).toList();
822	    }
823	
824	    /** Keep each of the tags (as {@link Tags} stores them) as used on the sheet. */
825	    public void keepTags(String sheetId, String tags) {
826	        for (String tag : Tags.of(tags)) {
827	            if (!sheetTags.existsBySheetIdAndTag(sheetId, tag)) {
828	                sheetTags.save(new SheetTag(sheetId, tag));
829	            }
830	        }
831	    }
832	
833	    public void refuseRefUsed(String sheetId, String ref, Long exceptId) {
834	        if (ref != null && claims.refUsed(sheetId, ref, exceptId)) {
835	            throw new ResponseStatusException(HttpStatus.CONFLICT,
836	                    "The reference \"" + ref + "\" is already used on this sheet");
837	        }
838	    }
839	
840	    private Person person(String sheetId, long personId) {
841	        return people.findByIdAndSheetId(personId, sheetId)
842	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet"));
843	    }
844	
845	    /** An audit record about a claim; one that has a number carries it at the end. */
846	    /** The end of a void's record: its reason, when one was given. */
847	    private static String reasonText(String voidReason) {
848	        return voidReason == null ? "" : " reason=" + voidReason;
849	    }
850	
851	    private static String record(String event, String sheetId, String user, Person person, Claim claim) {
852	        String number = claim.getNumber();
853	        return event + " sheet=" + sheetId + " by=" + user + " person=" + person.getName()
854	                + " amount=" + claim.getAmount().setScale(2).toPlainString() + " date=" + claim.getDate()
855	                + (number != null ? " number=" + number : "");
856	    }
857	}
