62	                    claim.getDate(), claim.getNote(), claim.getStatus(), claim.getNumber(),
63	                    claim.getSettledDue() == null ? null : claim.getSettledDue().setScale(2).toPlainString(),
64	                    claim.getOpenedBy(), claim.isStated(),
65	                    claim.getStatedDue() == null ? null : claim.getStatedDue().setScale(2).toPlainString(),
66	                    claim.isStatedNa(), claim.getCorrects(), claim.roundsBy(), claim.getListed(), claim.getDueBy(),
67	                    claim.getLog().stream().map(LogLineView::of).toList(), claim.getDeferredUntil(),
