76	        /** The claim as it stood at the end of a day: its figures as its revision then has them (see
77	         *  {@link History}), its log as far as that day, and its number and who opened it only once it
78	         *  had been opened by then; its proofs as given by that day; what no revision keeps (its note, reference, tags, where it is listed) as it is
79	         *  now (null: the claim is gone now; it is then listed last). No one has its editor open then. */
80	        static ClaimView asOf(Claim then, Claim now, LocalDate day) {
81	            Claim kept = now != null ? now : then;
82	            List<ClaimLog> log = kept.getLog().stream().filter(l -> !l.getOn().isAfter(day)).toList();
83	            boolean opened = kept.getLog().isEmpty() ? then.getStatus() != ClaimStatus.DRAFT
84	                    : log.stream().anyMatch(l -> l.getStatus() == ClaimStatus.OPEN);
85	            return new ClaimView(then.getId(), then.getPersonId(), then.getAmount().setScale(2).toPlainString(),
86	                    then.getDate(), kept.getNote(), then.getStatus(), opened ? kept.getNumber() : null,
87	                    then.getSettledDue() == null ? null : then.getSettledDue().setScale(2).toPlainString(),
88	                    opened ? kept.getOpenedBy() : null, then.isStated(),
89	                    then.getStatedDue() == null ? null : then.getStatedDue().setScale(2).toPlainString(),
90	                    then.isStatedNa(), kept.getCorrects(), then.roundsBy(),
91	                    kept.getListed() == null ? 0 : kept.getListed(), then.getDueBy(),
92	                    log.stream().map(LogLineView::of).toList(), then.getDeferredUntil(), kept.getProofsOn(day),
93	                    kept.getSplitFrom(), null, kept.isLateEntry(),
94	                    kept.getRemindedOn() == null || kept.getRemindedOn().isAfter(day) ? null : kept.getRemindedOn(),
95	                    kept.getRef(), tagsText(kept.getTags()),
96	                    then.getStatus() == ClaimStatus.VOID ? kept.getVoidReason() : null,
97	                    kept.getComments().stream().filter(c -> !c.getOn().isAfter(day)).map(CommentView::of).toList(),
98	                    batchOf(then.getStatus(), kept.getSettleBatch()),
99	                    kept.getLines().stream().map(LineView::of).toList());
100	        }
