200	    /** The claims on the sheet, newest first; as of a day when one is given, as they stood at the end
201	     *  of it (see {@link History}). */
202	    @GetMapping("/claims")
203	    public List<ClaimView> list(@PathVariable @NotBlank @Size(max = 100) String sheetId,
204	            @RequestHeader(value = AsOfGuard.HEADER, required = false) @DateTimeFormat(iso = DateTimeFormat.ISO.DATE)
205	            LocalDate asOf) {
