210	            return history.asOf(sheet, asOf).claims().stream()
211	                    .map(then -> ClaimView.asOf(then, now.get(then.getId()), asOf))
212	                    .sorted(Comparator.comparingLong(ClaimView::listed).reversed()).toList();
213	        }
