168	    /** The people on the sheet; as of a day when one is given, as they stood at the end of it (see
169	     *  {@link History}), that day standing in for the sheet's today. */
170	    @GetMapping
171	    public List<PersonView> list(@PathVariable @NotBlank @Size(max = 100) String sheetId,
172	            @RequestHeader(value = AsOfGuard.HEADER, required = false) @DateTimeFormat(iso = DateTimeFormat.ISO.DATE)
173	            LocalDate asOf) {
174	        String sheet = sheetId.trim();
175	        if (asOf != null) {
176	            Map<Long, StatementSummary> then = statements.summaries(sheet, asOf);
177	            Predicate<Person> clashingThen = service.clashing(sheet);
178	            Map<Long, Integer> place = new HashMap<>();
179	            List<Person> listed = service.list(sheet);
180	            for (int i = 0; i < listed.size(); i++) {
181	                place.put(listed.get(i).getId(), i);
182	            }
183	            return history.asOf(sheet, asOf).people().values().stream()
184	                    .sorted(Comparator.comparing((Person p) -> place.getOrDefault(p.getId(), Integer.MAX_VALUE))
185	                            .thenComparing(Person::getId))
186	                    .map(p -> PersonView.of(p, then.getOrDefault(p.getId(), StatementSummary.NONE), asOf,
187	                            clashingThen.test(p)))
188	                    .toList();
189	        }
190	        Map<Long, StatementSummary> summaries = statements.summaries(sheet);
191	        LocalDate today = sheets.today(sheet);
192	        Predicate<Person> clashing = service.clashing(sheet);
193	        return service.list(sheet).stream()
194	                .map(p -> PersonView.of(p, summaries.getOrDefault(p.getId(), StatementSummary.NONE), today,
195	                        clashing.test(p)))
196	                .toList();
197	    }
