  clashing: boolean;
  /** The sheet they were transferred from; null when they were not transferred. */
  origin: string | null;
  /** Their tags, sorted and comma and space separated; empty when they have none. */
  tags: string;
  /** Their snapshots, oldest first. */
  snapshots: Snapshot[];
}

