9	/** Where a claim is in its life: DRAFT, then OPEN, then SETTLED; a clerk's settle above the clerk
10	 *  limit leaves it PENDING until a steward approves it (SETTLED) or rejects it (OPEN again); a
11	 *  DRAFT, OPEN or PENDING claim may be VOID, and a steward may void a SETTLED one within 7 days of
12	 *  its settlement. A DRAFT may be DELETED (counting nowhere), and restored to DRAFT the same day. */
13	export type ClaimStatus = 'DRAFT' | 'OPEN' | 'PENDING' | 'SETTLED' | 'VOID' | 'DELETED';
14	
15	/** A change of status a claim can be asked for. */
16	export type ClaimAction = 'open' | 'settle' | 'resettle' | 'void' | 'approve' | 'reject' | 'delete' | 'restore';
17	
18	/** Whether a claim is open: OPEN, or PENDING approval of its settle. */
19	export function isOpen(c: Claim): boolean {
20	  return c.status === 'OPEN' || c.status === 'PENDING';
21	}
22	
23	/** Whether a claim at this status counts toward claimed, due-total and every total. */
24	export function counts(c: Claim): boolean {
25	  return isOpen(c) || c.status === 'SETTLED';
26	}
27	
28	/** Whether a claim is deferred on the sheet's today: it is OPEN and today is before the day it is
29	 *  deferred until. Until then it counts in no total, is not overdue and cannot be settled. */
30	export function deferred(c: Claim, today: string | null): boolean {
31	  return c.status === 'OPEN' && c.deferredUntil !== null && today !== null && today < c.deferredUntil;
32	}
33	
34	/** Whether a claim counts in the live totals on the sheet's today: it counts, it is not deferred,
35	 *  and it is not an open (or pending) claim, unbound by a statement, dated within one of its
36	 *  person's holds or of a person retired on that day. */
37	export function countsLive(c: Claim, leave: Leave, today: string | null): boolean {
38	  return counts(c) && !deferred(c, today) && !leftOut(c, leave, today);
39	}
40	
41	/** Whether the live rules leave a claim out: it is open (or pending), unbound by a statement, and
42	 *  dated within one of its person's holds or its person is retired on the sheet's today. */
43	function leftOut(c: Claim, leave: Leave, today: string | null): boolean {
44	  return isOpen(c) && !c.stated && (heldOn(leave.holds, c.date) || retiredOn(leave.retiredFrom, today));
45	}
46	
47	/** The day (yyyy-mm-dd) a number of days after another (before it when negative). */
48	export function addDays(day: string, days: number): string {
49	  const d = new Date(day + 'T00:00:00Z');
50	  d.setUTCDate(d.getUTCDate() + days);
51	  return d.toISOString().slice(0, 10);
52	}
53	
54	/** Whether a claim keeps its person active on the sheet's today: it is open (or pending), it
55	 *  counts in the live totals, and it is dated within the 30 days up to and including today. */
56	export function keepsActive(c: Claim, leave: Leave, today: string | null): boolean {
57	  return today !== null && isOpen(c) && countsLive(c, leave, today)
58	    && addDays(today, -29) <= c.date && c.date <= today;
59	}
60	
61	/** A claim's part in its patron's backing: its frozen figure when it is settled and dated within
62	 *  the 90 days up to and including the sheet's today; null otherwise. */
63	export function backingFigure(c: Claim, today: string | null): string | null {
64	  return today !== null && c.status === 'SETTLED' && addDays(today, -89) <= c.date && c.date <= today
65	    ? c.settledDue : null;
66	}
67	
68	/** The status a claim had at the end of the day, as its status log records it: that of the last
69	 *  line logged on or before the day; null when it was not yet made then. A claim with no log has
70	 *  its status now. */
71	export function statusOn(c: Claim, day: string): ClaimStatus | null {
72	  if (c.log.length === 0) return c.status;
73	  let then: ClaimStatus | null = null;
74	  for (const line of c.log) if (line.on <= day) then = line.status;
75	  return then;
76	}
77	
78	/** Whether a claim counts in a period's totals: by the status it had at the end of the period's
79	 *  last day it counts, and the live rules do not leave it out: it is not deferred on the sheet's
80	 *  today, and it is not a claim open (or pending) now, unbound by a statement, dated within one of
81	 *  its person's holds or of a person retired on the sheet's today. */
82	export function countsAsOf(c: Claim, leave: Leave, end: string, today: string | null): boolean {
83	  const then = statusOn(c, end);
84	  if (then === null || !(then === 'OPEN' || then === 'PENDING' || then === 'SETTLED')) return false;
85	  return !deferred(c, today) && !leftOut(c, leave, today);
86	}
