88	export interface Claim {
89	  id: number;
90	  personId: number;
91	  /** The amount as text with two decimals. */
92	  amount: string;
93	  date: string;
94	  note: string;
95	  status: ClaimStatus;
96	  /** The claim's number on the sheet, given when it is opened (1, 2, ... or, under period numbering,
97	   *  <period name>-<n>, or X-<n> for a claim in no period); null for a claim never opened. */
98	  number: string | null;
99	  /** The due fixed when the claim was settled, as text with two decimals; null when it is not
100	   *  settled, or was settled while its person's grade had no rate (its due then stays live). */
101	  settledDue: string | null;
102	  /** Who opened the claim; null when it was never opened. That user cannot settle it. */
103	  openedBy: string | null;
104	  /** Whether its person's last statement bound it to the due it had then. */
105	  stated: boolean;
106	  /** The due the last statement bound it to, as text with two decimals; null when it is unbound,
107	   *  or was bound while it had no due (its due then stays live). */
108	  statedDue: string | null;
109	  /** Whether the last statement bound it to n/a: the rate that would apply to it had ended (its
110	   *  due then does not stay live). */
111	  statedNa: boolean;
112	  /** The number of the settled claim this correction corrects; null when it is not a correction. */
113	  corrects: string | null;
114	  /** The date (yyyy-mm-dd) its figures round by: that of the claim a correction corrects, or else
115	   *  its own. */
116	  roundsBy: string;
117	  /** Where the claim is listed: claims are listed newest first by this (a claim moved to another
118	   *  person is listed as that person's newest). */
119	  listed: number;
120	  /** The day (yyyy-mm-dd) it is due by: fixed when it was made, the terms-th business day after its
121	   *  date by the terms of its person's grade in force on that date. */
122	  dueBy: string;
123	  /** Its status log, oldest first: a line for each status it has had. */
124	  log: ClaimLogLine[];
125	  /** The day (yyyy-mm-dd) it is deferred until; null when it was never deferred. */
126	  deferredUntil: string | null;
127	  /** How many proofs it has. One whose due is above the proof threshold in force on its date cannot
128	   *  be settled or approved while it has none. */
129	  proofs: number;
130	  /** The number of the claim it was split off; null when it was not split off one. */
131	  splitFrom: string | null;
132	  /** Who has the claim's editor open, locking it for every other user; null when no one has. */
133	  editLockedBy: string | null;
134	  /** Whether the claim was added while the period its due-by falls in was soft-closed. */
135	  lateEntry: boolean;
136	  /** The last day (yyyy-mm-dd) a reminder was written for it; null when never. */
137	  remindedOn: string | null;
138	  /** Its external reference; null when it has none. No two claims of a sheet share one, comparing
139	   *  without regard to case. */
140	  ref: string | null;
141	  /** Its tags, sorted and comma and space separated; empty when it has none. */
142	  tags: string;
143	  /** The reason from the sheet's list a void claim was voided with; null when none. */
144	  voidReason: string | null;
145	  /** Its comments, in the order they were written. */
146	  comments: ClaimComment[];
147	  /** The number of the bulk settle batch that settled it (or left it pending); null when it was
148	   *  settled one at a time, or is not settled or pending. */
149	  settleBatch: number | null;
150	  /** Its lines, in the order they were added; a claim with lines has their total as its amount. */
151	  lines: ClaimLine[];
