201	/** An amount with up to two decimals, 0.00 or more. */
202	export const AMOUNT = /^\d{1,12}(\.\d{1,2})?$/;
203	
204	/** A claim's amount with up to two decimals; a negative one is a correction. */
205	export const CLAIM_AMOUNT = /^-?\d{1,12}(\.\d{1,2})?$/;
206	
207	/** Whether a claim is a correction: its amount is below 0.00. */
208	export function correction(c: Claim): boolean {
209	  return c.amount.startsWith('-') && Number(c.amount) !== 0;
210	}
211	
212	/** The sum of amounts (two-decimal text), added in cents so no rounding creeps in. */
213	export function sumAmounts(amounts: string[]): string {
214	  const cents = amounts.reduce((sum, a) => sum + Math.round(Number(a) * 100), 0);
215	  return (cents / 100).toFixed(2);
216	}
217	
218	/** Amounts added up, leaving out the single highest and the single lowest when there are three or
219	 *  more. */
220	export function trimmedSum(amounts: string[]): string {
221	  if (amounts.length < 3) return sumAmounts(amounts);
222	  const sorted = [...amounts].sort((a, b) => Number(a) - Number(b));
223	  return sumAmounts(sorted.slice(1, -1));
224	}
225	
226	/** Whether a claim is bound by its person's last statement now: it was bound, and it is not
227	 *  pending (a pending claim shows its live figure). */
228	function bound(c: Claim): boolean {
229	  return c.stated && c.status !== 'PENDING';
230	}
231	
232	/** Whether a claim keeps a figure that rates and grades no longer change: settled or bound by a
233	 *  statement. */
234	export function fixed(c: Claim): boolean {
235	  return c.settledDue !== null || (bound(c) && (c.statedDue !== null || c.statedNa));
236	}
237	
238	/** What a claim's late charge follows: the sheet's today and its late percents (each 30-day boundary
239	 *  takes the one in force on it), and the grace days of each grade; and the sheet's policy date, which
240	 *  decides how its live figures round. */
241	export interface Lateness {
242	  today: string | null;
243	  /** The late percents recorded, each from its from-date, earliest first. */
244	  pcts: DatedValue[];
245	  /** The grace days recorded for each grade. */
246	  graces: Graces;
247	  /** The policy date set (yyyy-mm-dd); null when blank, the sheet's today then stands in. */
248	  policyDate: string | null;
249	}
250	
251	/** Whether a claim's live figures round half up: the date it rounds by is before the policy date
252	 *  in force (the one set, or else the sheet's today); otherwise they round half to even. */
253	export function roundsHalfUp(c: Claim, late: Lateness): boolean {
254	  const policy = late.policyDate ?? late.today;
255	  return policy !== null && c.roundsBy < policy;
256	}
257	
258	/** A claim's due figure: the one fixed when it was settled, or else the greater of the sheet's floor in force on the
259	 *  claim's date and its rate figure with the late charge on that figure on top while it is overdue. The rate figure is
260	 *  the one its person's last statement bound it to (n/a when it bound it to n/a), or else its live due at the rate in
261	 *  force on the claim's date for the grade (the person's grade in force on that date), rounded by the policy date (a
262	 *  settled claim's figure already holds the charge and the floor). A correction has no floor and no late charge. Null
263	 *  when there is none. */
264	export function claimDue(c: Claim, rates: Rate[], grade: Grade | undefined, floors: DatedValue[], late: Lateness): string | null {
265	  if (c.settledDue !== null) return c.settledDue;
266	  if (bound(c) && c.statedNa) return null;
267	  const live = due(c.amount, grade === undefined ? undefined : pctOn(rates, grade, c.date), roundsHalfUp(c, late));
268	  const figure = (bound(c) ? c.statedDue : null) ?? live;
269	  if (figure === null) return null;
270	  const charged = sumAmounts([figure, lateCharge(c, figure, late, grade)]);
271	  return correction(c) ? charged : atLeast(charged, valueOn(floors, c.date, STARTING_FLOOR));
272	}
273	
274	/** The late charge on an overdue claim (its grade being its person's grade in force on its date): for each full
275	 *  30 days it is overdue, the late percent in force on that boundary (its late-from plus 30, 60, 90 ... days) of its
276	 *  figure plus the charges of the boundaries before it (the charge compounds), rounded like a due, the charges added
277	 *  up (a boundary whose percent is 0.00 adds nothing); 0.00 when it is not overdue, and on a correction. */
278	export function lateCharge(c: Claim, figure: string, late: Lateness, grade: Grade | undefined): string {
279	  if (correction(c)) return '0.00';
280	  const grace = graceOn(late.graces, grade, c.date);
281	  if (!overdue(c, late.today, grace) || late.today === null) return '0.00';
282	  const from = Date.parse(lateFrom(c, grace));
283	  const days = (Date.parse(late.today) - from) / 86_400_000;
284	  const periods = Math.floor(days / 30);
285	  if (periods <= 0) return '0.00';
286	  const charges: string[] = [];
287	  for (let n = 1; n <= periods; n++) {
288	    const boundary = new Date(from + n * 30 * 86_400_000).toISOString().slice(0, 10);
289	    const pct = valueOn(late.pcts, boundary, STARTING_LATE_PCT);
290	    if (Number(pct) !== 0) charges.push(due(sumAmounts([figure, ...charges]), pct, roundsHalfUp(c, late)) ?? '0.00');
291	  }
292	  return sumAmounts(charges);
293	}
294	
295	/** The day a claim's lateness counts from: its due-by plus its grace days (those in force on its date
296	 *  for its person's grade in force on that date). The due-by it shows is unchanged. */
297	export function lateFrom(c: Claim, grace: number): string {
298	  return grace === 0 ? c.dueBy : addDays(c.dueBy, grace);
299	}
300	
301	/** Whether a claim is overdue: it is open (or pending), not deferred, and its due-by plus its grace
302	 *  days is before the sheet's today. */
303	export function overdue(c: Claim, today: string | null, grace = 0): boolean {
304	  return isOpen(c) && !deferred(c, today) && today !== null && lateFrom(c, grace) < today;
305	}
