463	        { headers: { 'X-User': user } }),
464	    );
465	  }
466	
467	  /** Move a draft, open or pending claim to another person on the sheet; refused (403) unless the
468	   *  user is a steward, and (409) when the claim is settled or void. */
469	  reassign(id: number, personId: number): Promise<Claim> {
470	    const { sheetId, user } = this.active();
471	    return firstValueFrom(
472	      this.http.post<Claim>(`${this.url(sheetId)}/claims/${id}/reassign`, { personId }, { headers: { 'X-User': user } }),
473	    );
474	  }
475	
476	  /** Open each of the claims that can be opened, in list order; the rest are refused and left as
477	   *  they are. */
478	  openAll(claimIds: number[]): Promise<{ opened: number; refused: number }> {
479	    const { sheetId, user } = this.active();
480	    return firstValueFrom(
481	      this.http.post<{ opened: number; refused: number }>(`${this.url(sheetId)}/claims/open`, { claimIds },
482	        { headers: { 'X-User': user } }),
483	    );
484	  }
485	
486	  /** Settle each of the claims that can be settled, in list order, as settling one does (one left
487	   *  pending a steward's approval counts as settled); the rest are refused and left as they are. */
488	  settleAll(claimIds: number[]): Promise<{ settled: number; refused: number }> {
489	    const { sheetId, user } = this.active();
490	    return firstValueFrom(
491	      this.http.post<{ settled: number; refused: number }>(`${this.url(sheetId)}/claims/settle`, { claimIds },
492	        { headers: { 'X-User': user } }),
493	    );
494	  }
495	
496	  /** Move each of the selected claims that can be moved to the person, in list order, as moving
497	   *  one does; the rest are refused and left as they are. */
498	  reassignAll(claimIds: number[], personId: number): Promise<{ reassigned: number; refused: number }> {
499	    const { sheetId, user } = this.active();
500	    return firstValueFrom(
501	      this.http.post<{ reassigned: number; refused: number }>(`${this.url(sheetId)}/claims/reassign`,
502	        { claimIds, personId }, { headers: { 'X-User': user } }),
503	    );
504	  }
505	
506	  /** Re-date each of the claims that can be re-dated, in list order, as re-dating one does; the
507	   *  rest are refused and left as they are. */
508	  redateAll(claimIds: number[], date: string): Promise<{ redated: number; refused: number }> {
509	    const { sheetId, user } = this.active();
510	    return firstValueFrom(
511	      this.http.post<{ redated: number; refused: number }>(`${this.url(sheetId)}/claims/redate`,
512	        { claimIds, date }, { headers: { 'X-User': user } }),
513	    );
514	  }
515	
516	  private url(sheetId: string): string {
517	    return `/api/sheets/${encodeURIComponent(sheetId)}`;
518	  }
519	
520	  private active(): { sheetId: string; user: string } {
521	    const sheetId = this.session.sheetId();
522	    const user = this.session.user();
523	    if (!sheetId || !user) throw new Error('no sheet loaded');
524	    return { sheetId, user };
525	  }
526	}
